<?php
$cv=$cv??[];$educations=$educations??[];$workHistories=$workHistories??[];$certificatesOfCv=$certificatesOfCv??[];$skillsOfCv=$skillsOfCv??[];
$h=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');
$pick=function($r,$keys,$d=''){foreach((array)$keys as $k){if(isset($r[$k])&&$r[$k]!=='')return $r[$k];}return $d;};
$name=$pick($cv,['full_name','name'],'Untitled CV');$id=$pick($cv,['id','cv_id'],'');$category=$pick($cv,['category_name','category'],'Creative Professional');$email=$pick($cv,'email');$phone=$pick($cv,['phone_number','phone']);$dob=$pick($cv,['date_of_birth','dob']);$gender=$pick($cv,'gender');$location=implode(', ',array_filter([$pick($cv,['street_address','address']),$pick($cv,['district_name','district']),$pick($cv,['city_name','city']),$pick($cv,['country_name','country'])]));$period=fn($r)=>trim(($pick($r,'start_year')?:'').' - '.($pick($r,'end_year')?:'Present'));$initials=strtoupper(substr(trim($name),0,1));
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Modern CV</title><style>
:root{--bg:#eef2ff;--panel:#fff;--ink:#0f172a;--muted:#64748b;--line:#e2e8f0;--primary:#4f46e5;--cyan:#06b6d4;--soft:#f8fafc}*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:Segoe UI,Arial,sans-serif;color:var(--ink);background:radial-gradient(circle at top left,rgba(79,70,229,.24),transparent 32%),radial-gradient(circle at bottom right,rgba(6,182,212,.20),transparent 30%),var(--bg)}.page{width:min(1060px,calc(100% - 32px));margin:30px auto;background:var(--panel);border-radius:30px;overflow:hidden;box-shadow:0 28px 90px rgba(30,41,59,.18)}.hero{position:relative;display:grid;grid-template-columns:auto 1fr;gap:24px;align-items:center;padding:48px 54px;background:linear-gradient(135deg,#312e81,#4f46e5 58%,#06b6d4);color:#fff}.hero:after{content:"";position:absolute;right:-70px;top:-70px;width:230px;height:230px;border-radius:50%;border:38px solid rgba(255,255,255,.14)}.avatar{width:108px;height:108px;border-radius:30px;display:grid;place-items:center;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.28);font-size:40px;font-weight:900}.hero h1{margin:0;font-size:clamp(36px,5vw,58px);letter-spacing:-2px;line-height:1}.role{display:inline-flex;margin-top:12px;padding:8px 14px;background:rgba(255,255,255,.18);border-radius:999px;font-size:13px;font-weight:900;text-transform:uppercase}.summary{margin:18px 0 0;max-width:720px;line-height:1.7;color:rgba(255,255,255,.88)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.actions a{position:relative;z-index:1;text-decoration:none;border-radius:999px;padding:10px 15px;font-size:13px;font-weight:900}.actions .secondary{background:rgba(255,255,255,.18);color:#fff}.actions .edit{background:#fff;color:#312e81}.layout{display:grid;grid-template-columns:310px 1fr}.sidebar{padding:34px 28px;background:#f8fafc;border-right:1px solid var(--line)}.main{padding:34px 40px}.section{margin-bottom:32px}.title{display:flex;align-items:center;gap:10px;margin:0 0 16px;font-size:19px}.dot{width:12px;height:12px;border-radius:50%;background:linear-gradient(135deg,var(--primary),var(--cyan));box-shadow:0 0 0 5px rgba(79,70,229,.10)}.info{background:#fff;border:1px solid var(--line);border-radius:18px;padding:16px;margin-bottom:12px}.label{display:block;color:var(--muted);font-size:11px;font-weight:900;letter-spacing:1px;text-transform:uppercase;margin-bottom:5px}.value{font-size:14px;line-height:1.45;word-break:break-word}.skill{background:#fff;border:1px solid var(--line);border-radius:16px;padding:13px 14px;margin-bottom:10px}.bar{height:7px;border-radius:999px;background:#e2e8f0;overflow:hidden;margin-top:7px}.bar span{display:block;height:100%;width:75%;background:linear-gradient(90deg,var(--primary),var(--cyan))}.level{font-size:12px;color:var(--muted);margin-top:5px}.card{background:#fff;border:1px solid var(--line);border-radius:24px;padding:22px 24px;box-shadow:0 10px 28px rgba(15,23,42,.06);margin-bottom:16px}.card h3{margin:0 0 6px;font-size:19px}.meta{color:var(--muted);font-size:14px;margin-bottom:9px}.desc{line-height:1.65}.empty{color:var(--muted);font-style:italic}@media(max-width:840px){.hero,.layout{grid-template-columns:1fr}.sidebar{border-right:0;border-bottom:1px solid var(--line)}.hero{padding:36px 26px}.main{padding:28px 24px}}
</style></head><body><div class="page"><header class="hero"><div class="avatar"><?= $h($initials) ?></div><div><h1><?= $h($name) ?></h1><div class="role"><?= $h($category) ?></div><?php if(!empty($cv['summary'])):?><p class="summary"><?= nl2br($h($cv['summary'])) ?></p><?php endif;?><div class="actions"><a class="secondary" href="?route=seeker/cv/templates<?= $id?'&id='.$h($id):'' ?>">Change Template</a><a class="edit" href="?route=seeker/cv/edit">Edit CV</a></div></div></header><div class="layout"><aside class="sidebar"><section class="section"><h2 class="title"><span class="dot"></span>Contact</h2><?php foreach(['Email'=>$email,'Phone'=>$phone,'Date of Birth'=>$dob,'Gender'=>$gender,'Address'=>$location] as $k=>$v): if($v):?><div class="info"><span class="label"><?= $h($k) ?></span><div class="value"><?= $h($v) ?></div></div><?php endif; endforeach;?></section><section class="section"><h2 class="title"><span class="dot"></span>Skills</h2><?php if($skillsOfCv): foreach($skillsOfCv as $s):?><div class="skill"><strong><?= $h($pick($s,['skill_name','skill'],'Skill')) ?></strong><div class="bar"><span></span></div><div class="level"><?= $h($pick($s,['proficiency_name','proficiency'],'Proficiency')) ?></div></div><?php endforeach; else:?><p class="empty">No skills.</p><?php endif;?></section><section class="section"><h2 class="title"><span class="dot"></span>Certificates</h2><?php if($certificatesOfCv): foreach($certificatesOfCv as $c):?><div class="info"><strong><?= $h($pick($c,['certificate_name','certificate'],'Certificate')) ?></strong><div class="value"><?= $h(implode(' · ',array_filter([$pick($c,['organization_name','organization']),$pick($c,'year_issued')]))) ?></div></div><?php endforeach; else:?><p class="empty">No certificates.</p><?php endif;?></section></aside><main class="main"><section class="section"><h2 class="title"><span class="dot"></span>Education</h2><?php if($educations): foreach($educations as $e):?><article class="card"><h3><?= $h($pick($e,['degree_name','degree'],'Education')) ?></h3><div class="meta"><?= $h(implode(' · ',array_filter([$pick($e,['institution_name','institution']),$pick($e,['major_name','major']),$period($e)]))) ?></div><?php if($pick($e,'description')):?><div class="desc"><?= nl2br($h($pick($e,'description'))) ?></div><?php endif;?></article><?php endforeach; else:?><p class="empty">No education records.</p><?php endif;?></section><section class="section"><h2 class="title"><span class="dot"></span>Work History</h2><?php if($workHistories): foreach($workHistories as $w):?><article class="card"><h3><?= $h($pick($w,['job_title_name','job_title'],'Work Experience')) ?></h3><div class="meta"><?= $h(implode(' · ',array_filter([$pick($w,'company_name'),$pick($w,['employment_type_name','employment_type']),$pick($w,['industry_name','industry']),$period($w)]))) ?></div><?php if($pick($w,['job_description','description'])):?><div class="desc"><?= nl2br($h($pick($w,['job_description','description']))) ?></div><?php endif;?></article><?php endforeach; else:?><p class="empty">No work history records.</p><?php endif;?></section></main></div></div></body></html>
